use std::fs
use std::collections::BTreeMap

fn amount_of(s: string) -> int {
    s.parse::<int>().unwrap_or(0)
}

fn balance_of(m: BTreeMap<string, int>, name: string) -> int {
    m.get(name).copied().unwrap_or(0)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut accts: BTreeMap<string, int> = BTreeMap::new()
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().map(|x| x.to_string()).collect()
        if p.len() == 0 { continue }
        let cmd = p[0]
        if cmd == "open" && p.len() >= 3 {
            let amt = amount_of(p[2])
            if amt < 0 {
                println("error: invalid amount")
            } else if accts.contains_key(p[1]) {
                println("error: duplicate account")
            } else {
                accts.insert(p[1], amt)
                println("ok")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && p.len() >= 3 {
            let amt = amount_of(p[2])
            if amt <= 0 {
                println("error: invalid amount")
            } else if !accts.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else {
                let bal = balance_of(accts, p[1])
                if cmd == "deposit" {
                    accts.insert(p[1], bal + amt)
                    println("ok")
                } else if amt > bal {
                    println("error: insufficient funds")
                } else {
                    accts.insert(p[1], bal - amt)
                    println("ok")
                }
            }
        } else if cmd == "transfer" && p.len() >= 4 {
            let amt = amount_of(p[3])
            if amt <= 0 {
                println("error: invalid amount")
            } else if !accts.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else if !accts.contains_key(p[2]) {
                println("error: unknown account ${p[2]}")
            } else if p[1] == p[2] {
                println("error: same account")
            } else {
                let fb = balance_of(accts, p[1])
                let tb = balance_of(accts, p[2])
                if amt > fb {
                    println("error: insufficient funds")
                } else {
                    accts.insert(p[1], fb - amt)
                    accts.insert(p[2], tb + amt)
                    println("ok")
                }
            }
        } else if cmd == "balance" && p.len() >= 2 {
            if !accts.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else {
                println("${balance_of(accts, p[1])}")
            }
        }
    }
    for (k, v) in accts {
        println("${k} ${v}")
    }
}

